package com.unicarona.privacy;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.unicarona.UniCaronaApplication;
import com.unicarona.auth.config.AuthSettings;
import com.unicarona.file.config.StorageSettings;
import com.unicarona.payment.ledger.AccountKind;
import com.unicarona.payment.service.LedgerService;
import com.unicarona.privacy.config.*;
import com.unicarona.privacy.service.*;
import com.unicarona.reservation.repository.ReservationReadRepository;
import com.unicarona.reservation.service.LifecycleTransactions;
import com.unicarona.security.*;
import com.unicarona.shared.ApiException;
import com.unicarona.support.*;
import com.unicarona.support.PaidReservationFixture.Paid;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.env.MockEnvironment;
import static org.junit.jupiter.api.Assertions.*;

class BoardingPinRetentionIT {
    @TempDir Path temporary;private static RealPostgres database;private ServletWebServerApplicationContext app;private JdbcTemplate sql;private String[] args;private Paid expired,live;private List<String> originalMoney;private Path beforeBootstrap;private String expiredCipherBeforeBootstrap,expiredPinBeforeBootstrap,rescheduledExpiredPinBeforeBootstrap;private Timestamp originalDeadline;
    @BeforeAll static void database(){database=new RealPostgres();}
    @AfterAll static void databaseClose(){if(database!=null)database.close();}
    @AfterEach void close(){if(app!=null){app.close();app=null;}}
    @BeforeEach void setup()throws Exception {
        database.resetSchema();Flyway.configure().dataSource(database.dataSource()).locations("classpath:db/migration").target("45").cleanDisabled(true).load().migrate();sql=new JdbcTemplate(database.dataSource());expired=PaidReservationFixture.create(sql,-1,"America/Sao_Paulo");live=PaidReservationFixture.create(sql,1,"America/Sao_Paulo");originalMoney=money();
        var values=new ArrayList<>(List.of(AuthTestSettings.arguments(database.apiConnectionUrl())));values.addAll(List.of("--STORAGE_PATH="+temporary.resolve("files"),"--FRONTEND_PATH="+temporary.resolve("public"),"--PRIVACY_OPERATIONS_ROOT="+temporary.resolve("ops"),"--PRIVACY_ERASURE_JOURNAL_PATH="+temporary.resolve("journal"),"--DEV_MAIL_PATH="+temporary.resolve("mail")));args=values.toArray(String[]::new);
        var env=new MockEnvironment();for(String arg:args){int at=arg.indexOf('=');env.withProperty(arg.substring(2,at),arg.substring(at+1));}var json=new ObjectMapper();var crypto=new CryptoService();var auth=new AuthSettings(env);var files=new StorageSettings(env);var catalog=new PrivacyBackupCatalog(new PrivacyOperationsSettings(env,files),new PrivacySettings(env),new PrivacySigningKeys(env,auth,crypto,json),json,Clock.systemUTC());catalog.initialize();
        Flyway.configure().dataSource(database.dataSource()).locations("classpath:db/migration").cleanDisabled(true).load().migrate();var fence=new PrivacyRestoreFence(catalog,sql);fence.checkBeforeReplay();fence.markObserved();
        expiredCipherBeforeBootstrap=sql.queryForObject("SELECT pin_ciphertext FROM ride_reservations WHERE id=?",String.class,expired.id());originalDeadline=sql.queryForObject("SELECT pin_expires_at FROM ride_reservations WHERE id=?",Timestamp.class,expired.id());var reader=new ReservationReadRepository(sql,crypto,auth);expiredPinBeforeBootstrap=reader.list(expired.passenger(),"passenger",null,null,false,20,0,expired.id()).getFirst().pin();
        LocalDate originalDate=sql.queryForObject("SELECT ride_date FROM rides WHERE id=?",LocalDate.class,expired.ride());sql.update("UPDATE rides SET ride_date=current_date+2 WHERE id=?",expired.ride());rescheduledExpiredPinBeforeBootstrap=reader.list(expired.passenger(),"passenger",null,null,false,20,0,expired.id()).getFirst().pin();sql.update("UPDATE rides SET ride_date=? WHERE id=?",originalDate,expired.ride());
        beforeBootstrap=temporary.resolve("expired-pin-before-bootstrap.dump");database.dumpDatabaseArchive(beforeBootstrap);start();
    }
    private void start(){app=(ServletWebServerApplicationContext)new SpringApplicationBuilder(UniCaronaApplication.class).run(args);sql=app.getBean(JdbcTemplate.class);}
    private List<String> money(){return sql.queryForList("SELECT 'payments:'||to_jsonb(p)::text FROM payments p UNION ALL SELECT 'parcels:'||to_jsonb(p)::text FROM parcels p UNION ALL SELECT 'journals:'||to_jsonb(j)::text FROM ledger_transactions j UNION ALL SELECT 'entries:'||to_jsonb(e)::text FROM ledger_entries e ORDER BY 1",String.class);}
    private void erased(Paid p){assertTrue(Boolean.TRUE.equals(sql.queryForObject("SELECT pin_ciphertext IS NULL AND pin_hash IS NULL AND pin_erased_at IS NOT NULL FROM ride_reservations WHERE id=?",Boolean.class,p.id())));}
    private String pin(Paid p,UUID viewer){var values=app.getBean(ReservationReadRepository.class).list(viewer,viewer.equals(p.passenger())?"passenger":"driver",null,null,false,20,0,p.id());assertEquals(1,values.size());return values.getFirst().pin();}
    private Actor actor(UUID id){return new Actor(id,"user","active",UUID.randomUUID(),UUID.randomUUID(),"synthetic",true,Set.of("ROLE_USER"));}
    private void today(Paid p){RideFixtureClock.today(sql,p.ride());}
    private String key(){return "pin-"+UUID.randomUUID();}
    private PrivacyBoardingPinRetention.Candidate candidate(Paid p){return new PrivacyBoardingPinRetention.Candidate(p.id(),p.ride(),p.passenger(),p.driver());}
    private void restore(Path dump)throws Exception{app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(dump);start();}
    @Test void legacyExpiryIsPhysicallySuppressedBeforeReadinessWithoutRewritingMoney(){erased(expired);assertNull(pin(expired,expired.passenger()));assertEquals(originalMoney,money());assertTrue(app.getBean(PrivacyReadiness.class).ready());assertEquals(0,app.getBean(LedgerService.class).reconciliation().difference());}
    @Test void availableFutureCredentialBelongsOnlyToItsPassenger(){assertEquals(live.pin(),pin(live,live.passenger()));assertNull(pin(live,live.driver()));assertFalse(Boolean.TRUE.equals(sql.queryForObject("SELECT pin_erased_at IS NOT NULL FROM ride_reservations WHERE id=?",Boolean.class,live.id())));assertFalse(app.getBean(PrivacyBoardingPinRetention.class).retire(candidate(live),false));}
    @Test void boardingErasesTheCredentialAndKeepsProofIdempotencyAndMoney(){today(live);String key=key();var service=app.getBean(LifecycleTransactions.class);var response=service.board(actor(live.driver()),live.id().toString(),live.pin(),key);erased(live);assertNull(pin(live,live.passenger()));assertEquals(response,service.board(actor(live.driver()),live.id().toString(),live.pin(),key));assertEquals("BOARDING_UNAVAILABLE",assertThrows(ApiException.class,()->service.board(actor(live.driver()),live.id().toString(),live.pin(),key())).code());assertNotNull(sql.queryForObject("SELECT boarded_at FROM ride_reservations WHERE id=?",Timestamp.class,live.id()));assertEquals(1,sql.queryForObject("SELECT count(*) FROM audit_logs WHERE action='boarding_registered' AND resource_id=?",Integer.class,live.id()));assertEquals(originalMoney,money());}
    @Test void wrongPinDoesNotDestroyTheValidCredentialOrCreateBoarding(){today(live);assertEquals("PIN_INVALID",assertThrows(ApiException.class,()->app.getBean(LifecycleTransactions.class).board(actor(live.driver()),live.id().toString(),"0000",key())).code());assertEquals(live.pin(),pin(live,live.passenger()));assertNull(sql.queryForObject("SELECT boarded_at FROM ride_reservations WHERE id=?",Timestamp.class,live.id()));assertEquals(originalMoney,money());}
    @Test void driverCancellationRetiresPinAndPreservesTheActualCreditRule(){app.getBean(LifecycleTransactions.class).cancelRide(actor(live.driver()),live.ride().toString(),"Synthetic driver cancellation",key());erased(live);assertNull(pin(live,live.passenger()));assertEquals(500,app.getBean(LedgerService.class).balance(live.passenger(),AccountKind.PASSENGER_CREDIT));assertEquals(0,app.getBean(LedgerService.class).balance(live.passenger(),AccountKind.FUTURE));assertEquals(0,app.getBean(LedgerService.class).reconciliation().difference());}
    @Test void passengerCancellationRetiresPinWithoutDiscardingTheDispute(){app.getBean(LifecycleTransactions.class).cancelPassenger(actor(live.passenger()),live.id().toString(),"Synthetic passenger cancellation",key());erased(live);assertEquals("blocked",sql.queryForObject("SELECT status FROM parcels WHERE id=?",String.class,live.parcel()));assertEquals(1,sql.queryForObject("SELECT count(*) FROM occurrences WHERE reservation_id=? AND status='pending'",Integer.class,live.id()));}
    @Test void currentCredentialCannotBeClearedPartiallyChangedOrGivenANewDeadline(){for(String set:List.of("pin_hash=NULL","pin_ciphertext=NULL,pin_hash=NULL","pin_ciphertext='replacement'","pin_expires_at=pin_expires_at+interval '1 day'","pin_erased_at=now()","boarded_at=now()","status='boarded'")){assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->sql.update("UPDATE ride_reservations SET "+set+" WHERE id=?",live.id()));}assertEquals(live.pin(),pin(live,live.passenger()));assertEquals(originalMoney,money());}
    @Test void erasedCredentialAndOriginalBoardingProofCannotBeReintroducedOrReset(){today(live);app.getBean(LifecycleTransactions.class).board(actor(live.driver()),live.id().toString(),live.pin(),key());for(String set:List.of("pin_erased_at=NULL","boarded_at=NULL","status='confirmed'")){assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->sql.update("UPDATE ride_reservations SET "+set+" WHERE id=?",live.id()));}assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->sql.update("UPDATE ride_reservations SET pin_ciphertext=?,pin_hash=? WHERE id=?",live.cipher(),live.hash(),live.id()));erased(live);}
    @Test void originalDeadlineDoesNotMoveWhenRideOrCampusTimeZoneChanges(){Timestamp deadline=sql.queryForObject("SELECT pin_expires_at FROM ride_reservations WHERE id=?",Timestamp.class,live.id());sql.update("UPDATE rides SET ride_date=ride_date+30 WHERE id=?",live.ride());sql.update("UPDATE universities SET time_zone='America/Manaus' WHERE id=?",live.university());assertEquals(deadline,sql.queryForObject("SELECT pin_expires_at FROM ride_reservations WHERE id=?",Timestamp.class,live.id()));assertEquals(live.pin(),pin(live,live.passenger()));}
    @Test void expiredProjectionRejectsTheCredentialEvenBeforeBootstrapErasesItsBytes(){assertEquals(expired.cipher(),expiredCipherBeforeBootstrap);assertNull(expiredPinBeforeBootstrap);assertNull(rescheduledExpiredPinBeforeBootstrap,"A later ride date cannot reopen an expired original credential, even while its bytes are still present.");assertEquals("BOARDING_UNAVAILABLE",assertThrows(ApiException.class,()->app.getBean(LifecycleTransactions.class).board(actor(expired.driver()),expired.id().toString(),expired.pin(),key())).code());assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->sql.update("UPDATE ride_reservations SET status='boarded',boarded_at=now() WHERE id=?",expired.id()));assertEquals(originalMoney,money());}
    @Test void restoringAnExpiredCredentialDoesNotRenewItsWindowOrExposeItsCiphertext()throws Exception {restore(beforeBootstrap);erased(expired);assertNull(pin(expired,expired.passenger()));assertEquals(originalDeadline,sql.queryForObject("SELECT pin_expires_at FROM ride_reservations WHERE id=?",Timestamp.class,expired.id()));assertTrue(app.getBean(PrivacyReadiness.class).ready());assertEquals(originalMoney,money());assertEquals(0,app.getBean(LedgerService.class).reconciliation().difference());}
    @Test void anAlreadyErasedCopyKeepsItsOriginalErasureMarkerOnRestore()throws Exception {Timestamp erasedAt=sql.queryForObject("SELECT pin_erased_at FROM ride_reservations WHERE id=?",Timestamp.class,expired.id());Path dump=temporary.resolve("already-erased-pin.dump");database.dumpDatabaseArchive(dump);restore(dump);erased(expired);assertEquals(erasedAt,sql.queryForObject("SELECT pin_erased_at FROM ride_reservations WHERE id=?",Timestamp.class,expired.id()));assertEquals(live.pin(),pin(live,live.passenger()));}
    @Test void closingAnAccountDoesNotMakeItsCredentialPartOfFinancialProof(){sql.update("UPDATE users SET account_status='deleted',deleted_at=now() WHERE id=?",live.passenger());assertNull(pin(live,live.passenger()));assertTrue(app.getBean(PrivacyBoardingPinRetention.class).retire(candidate(live),false));erased(live);assertEquals(originalMoney,money());}
    @Test void aBusyOwnerDoesNotStarveOtherCredentialsWhosePurposeEnded()throws Exception {var free=PaidReservationFixture.create(sql,1,"America/Sao_Paulo");var before=money();for(var p:List.of(live,free))sql.update("UPDATE users SET account_status='deleted',deleted_at=now() WHERE id=?",p.passenger());try(var connection=database.dataSource().getConnection()){connection.setAutoCommit(false);try(var lock=connection.prepareStatement("SELECT id FROM users WHERE id=? FOR UPDATE")){lock.setObject(1,live.passenger());lock.executeQuery().close();}assertEquals(1,app.getBean(PrivacyBoardingPinMaintenance.class).runOnce(100,()->false));erased(free);assertNotNull(sql.queryForObject("SELECT pin_ciphertext FROM ride_reservations WHERE id=?",String.class,live.id()));connection.rollback();}assertEquals(1,app.getBean(PrivacyBoardingPinMaintenance.class).runOnce(100,()->false));erased(live);assertEquals(before,money());}
    @Test void ownerExportContainsLifecycleDatesWithoutCredentialMaterialOrOtherReservations()throws Exception {
        today(live);app.getBean(LifecycleTransactions.class).board(actor(live.driver()),live.id().toString(),live.pin(),key());var output=new java.io.ByteArrayOutputStream();app.getBean(PrivacyExportService.class).write(live.passenger(),output);
        com.fasterxml.jackson.databind.JsonNode data=null;try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(output.toByteArray()))){java.util.zip.ZipEntry entry;while((entry=zip.getNextEntry())!=null)if(entry.getName().equals("dados.json"))data=app.getBean(ObjectMapper.class).readTree(zip.readAllBytes());}assertNotNull(data);var rows=data.path("reservations");assertEquals(1,rows.size());var row=rows.get(0);assertEquals(live.id().toString(),row.path("id").asText());assertTrue(row.hasNonNull("pin_expires_at"));assertTrue(row.hasNonNull("pin_erased_at"));for(String field:List.of("pin","pin_ciphertext","pin_hash"))assertFalse(row.has(field));assertFalse(data.toString().contains(live.cipher()));assertFalse(data.toString().contains(live.hash()));assertFalse(data.toString().contains(expired.id().toString()));
    }
}
